#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include "src/demangle.h"

int main(int argc, char** argv) {
  if (argc < 2) return 1;
  FILE* f = fopen(argv[1], "rb");
  if (!f) return 1;
  fseek(f, 0, SEEK_END);
  long sz = ftell(f);
  fseek(f, 0, SEEK_SET);
  std::vector<unsigned char> data(sz);
  fread(data.data(), 1, sz, f);
  fclose(f);
  unsigned Size = data.size();
  if (Size >= 4095) return 0;
  char Buffer[Size + 1];
  std::memcpy(Buffer, data.data(), Size);
  Buffer[Size] = 0;
  char demangled[4096];
  google::Demangle(Buffer, demangled, Size);
  return 0;
}
EOF
